def cap_images(items, limit: int):
    """Fit a Responses input under a per-request image limit.

    Keeps the first image (the task's initial observation) and the most recent ones; each older
    image is replaced in place by a short text note so the turn structure is unchanged.
    Returns the (copied) input and the number of images replaced.
    """
    if not isinstance(items, list) or limit < 2:
        return items, 0
    paths = []

    def walk(value, path):
        if isinstance(value, dict):
            if value.get("type") == "input_image":
                paths.append(path)
                return
            for key, child in value.items():
                walk(child, path + (key,))
        elif isinstance(value, list):
            for index, child in enumerate(value):
                walk(child, path + (index,))

    walk(items, ())
    excess = len(paths) - limit
    if excess <= 0:
        return items, 0
    items = copy.deepcopy(items)
    for path in paths[1:1 + excess]:
        parent = items
        for key in path[:-1]:
            parent = parent[key]
        parent[path[-1]] = {"type": "input_text", "text": IMAGE_OMITTED.format(limit=limit)}
    return items, excess


